// Client-owned UI state in Zustand, with selectors as the store's public API
import { create } from 'zustand';
import { useShallow } from 'zustand/react/shallow';

type Panel = 'none' | 'filters' | 'details';

type GridUiState = {
  selectedIds: ReadonlySet<string>;
  openPanel: Panel;
  columnWidths: Record<string, number>;
  toggleRow: (id: string) => void;
  clearSelection: () => void;
  setPanel: (p: Panel) => void;
  resizeColumn: (col: string, width: number) => void;
};

export const useGridUi = create<GridUiState>()((set) => ({
  selectedIds: new Set(),
  openPanel: 'none',
  columnWidths: {},
  toggleRow: (id) =>
    set((s) => {
      const next = new Set(s.selectedIds);
      if (next.has(id)) next.delete(id);
      else next.add(id);
      return { selectedIds: next };
    }),
  clearSelection: () => set({ selectedIds: new Set() }),
  setPanel: (openPanel) => set({ openPanel }),
  resizeColumn: (col, width) => set((s) => ({ columnWidths: { ...s.columnWidths, [col]: width } })),
}));

// A row re-renders only when ITS selected flag flips, not when any selection changes.
export const useIsSelected = (id: string) => useGridUi((s) => s.selectedIds.has(id));

// Selecting several values: useShallow avoids a new-object-every-time re-render.
export const usePanelControls = () =>
  useGridUi(useShallow((s) => ({ openPanel: s.openPanel, setPanel: s.setPanel })));

export const useSelectedCount = () => useGridUi((s) => s.selectedIds.size);

// URL as state in the Next.js App Router: validated, debounced, history-friendly
'use client';
import { usePathname, useRouter, useSearchParams } from 'next/navigation';
import { useEffect, useMemo, useState } from 'react';
import { z } from 'zod';

const filtersSchema = z.object({
  q: z.string().max(100).catch(''),
  sort: z.enum(['newest', 'price-asc', 'price-desc']).catch('newest'),
  page: z.coerce.number().int().min(1).catch(1),
});
export type Filters = z.infer<typeof filtersSchema>;
const defaults: Filters = { q: '', sort: 'newest', page: 1 };

export function useFilters() {
  const params = useSearchParams();
  const router = useRouter();
  const pathname = usePathname();

  const filters = useMemo(() => filtersSchema.parse(Object.fromEntries(params)), [params]);

  function setFilters(patch: Partial<Filters>, mode: 'push' | 'replace' = 'push') {
    const next = { ...filters, ...patch, page: patch.page ?? 1 };
    const sp = new URLSearchParams();
    for (const [k, v] of Object.entries(next)) {
      if (v !== defaults[k as keyof Filters]) sp.set(k, String(v)); // keep defaults out of the URL
    }
    const url = sp.size ? `${pathname}?${sp}` : pathname;
    router[mode](url, { scroll: false });
  }

  return { filters, setFilters };
}

export function SearchBox() {
  const { filters, setFilters } = useFilters();
  const [draft, setDraft] = useState(filters.q);

  useEffect(() => {
    if (draft === filters.q) return;
    const t = setTimeout(() => setFilters({ q: draft }, 'replace'), 300); // no history entry per keystroke
    return () => clearTimeout(t);
  }, [draft, filters.q]); // eslint-disable-line react-hooks/exhaustive-deps

  return <input type="search" aria-label="Search" value={draft} onChange={(e) => setDraft(e.target.value)} />;
}

// Optimistic like with rollback (TanStack Query v5)
import { queryOptions, useMutation, useQuery, useQueryClient } from '@tanstack/react-query';

type Post = { id: string; title: string; liked: boolean; likes: number; version: number };

export const postKeys = {
  all: ['posts'] as const,
  lists: () => [...postKeys.all, 'list'] as const,
  detail: (id: string) => [...postKeys.all, 'detail', id] as const,
};

export const postQuery = (id: string) =>
  queryOptions({
    queryKey: postKeys.detail(id),
    queryFn: async ({ signal }): Promise<Post> => {
      const res = await fetch(`/api/posts/${id}`, { signal });
      if (!res.ok) throw new Error(`HTTP ${res.status}`);
      return res.json();
    },
    staleTime: 30_000,
  });

async function setLiked(id: string, liked: boolean): Promise<Post> {
  // Idempotent: "set liked = x", never "toggle"
  const res = await fetch(`/api/posts/${id}/like`, { method: 'PUT', body: JSON.stringify({ liked }) });
  if (!res.ok) throw new Error('like failed');
  return res.json();
}

export function useLikePost(id: string) {
  const qc = useQueryClient();
  return useMutation({
    mutationFn: (liked: boolean) => setLiked(id, liked),
    scope: { id: `post-${id}` }, // mutations for one post run one after another
    onMutate: async (liked) => {
      await qc.cancelQueries({ queryKey: postKeys.detail(id) });
      const previous = qc.getQueryData<Post>(postKeys.detail(id));
      if (previous) {
        qc.setQueryData<Post>(postKeys.detail(id), {
          ...previous,
          liked,
          likes: previous.likes + (liked === previous.liked ? 0 : liked ? 1 : -1),
        });
      }
      return { previous };
    },
    onError: (_err, _liked, ctx) => {
      if (ctx?.previous) qc.setQueryData(postKeys.detail(id), ctx.previous);
    },
    onSettled: () => qc.invalidateQueries({ queryKey: postKeys.all }), // detail and lists converge
  });
}

export function LikeButton({ id }: { id: string }) {
  const { data } = useQuery(postQuery(id));
  const like = useLikePost(id);
  if (!data) return null;
  return (
    <button aria-pressed={data.liked} onClick={() => like.mutate(!data.liked)}>
      {data.liked ? 'Liked' : 'Like'} ({data.likes})
    </button>
  );
}

// Compound Tabs with controlled/uncontrolled support and roving keyboard focus
'use client';
import { createContext, useCallback, useContext, useId, useRef, useState, type KeyboardEvent, type ReactNode } from 'react';

export function useControllableState<T>(opts: { value?: T; defaultValue: T; onChange?: (v: T) => void }) {
  const [inner, setInner] = useState(opts.defaultValue);
  const isControlled = opts.value !== undefined;
  const value = isControlled ? (opts.value as T) : inner;
  const setValue = useCallback(
    (next: T) => {
      if (!isControlled) setInner(next);
      opts.onChange?.(next);
    },
    [isControlled, opts.onChange], // eslint-disable-line react-hooks/exhaustive-deps
  );
  return [value, setValue] as const;
}

type TabsCtx = { value: string; select: (v: string) => void; baseId: string };
const Ctx = createContext<TabsCtx | null>(null);
function useTabs(part: string): TabsCtx {
  const ctx = useContext(Ctx);
  if (!ctx) throw new Error(`<Tabs.${part}> must be used inside <Tabs>`);
  return ctx;
}

type TabsProps = { value?: string; defaultValue: string; onValueChange?: (v: string) => void; children: ReactNode };

function TabsRoot({ value, defaultValue, onValueChange, children }: TabsProps) {
  const [current, select] = useControllableState({ value, defaultValue, onChange: onValueChange });
  const baseId = useId();
  return <Ctx.Provider value={{ value: current, select, baseId }}>{children}</Ctx.Provider>;
}

function List({ children, label }: { children: ReactNode; label: string }) {
  const ref = useRef<HTMLDivElement>(null);
  function onKeyDown(e: KeyboardEvent) {
    const tabs = [...(ref.current?.querySelectorAll<HTMLButtonElement>('[role="tab"]') ?? [])];
    const i = tabs.indexOf(document.activeElement as HTMLButtonElement);
    const next = e.key === 'ArrowRight' ? i + 1 : e.key === 'ArrowLeft' ? i - 1 : e.key === 'Home' ? 0 : e.key === 'End' ? tabs.length - 1 : null;
    if (next === null || i === -1) return;
    e.preventDefault();
    const target = tabs[(next + tabs.length) % tabs.length];
    target.focus();
    target.click(); // automatic activation
  }
  return (
    <div role="tablist" aria-label={label} ref={ref} onKeyDown={onKeyDown}>
      {children}
    </div>
  );
}

function Trigger({ value, children }: { value: string; children: ReactNode }) {
  const t = useTabs('Trigger');
  const selected = t.value === value;
  return (
    <button
      type="button"
      role="tab"
      id={`${t.baseId}-tab-${value}`}
      aria-selected={selected}
      aria-controls={`${t.baseId}-panel-${value}`}
      tabIndex={selected ? 0 : -1}
      data-state={selected ? 'active' : 'inactive'}
      onClick={() => t.select(value)}
    >
      {children}
    </button>
  );
}

function Content({ value, children }: { value: string; children: ReactNode }) {
  const t = useTabs('Content');
  if (t.value !== value) return null;
  return (
    <div role="tabpanel" id={`${t.baseId}-panel-${value}`} aria-labelledby={`${t.baseId}-tab-${value}`} tabIndex={0}>
      {children}
    </div>
  );
}

export const Tabs = Object.assign(TabsRoot, { List, Trigger, Content });

