// shell/src/remote-slot.tsx — one remote failing must not blank the page
import { Component, lazy, Suspense, type ComponentType, type ReactNode } from 'react';

class RemoteBoundary extends Component<{ name: string; fallback: ReactNode; children: ReactNode }, { failed: boolean }> {
  state = { failed: false };
  static getDerivedStateFromError() {
    return { failed: true };
  }
  componentDidCatch(error: unknown) {
    console.error(`remote ${this.props.name} failed`, error); // report to error tracking
  }
  render() {
    return this.state.failed ? this.props.fallback : this.props.children;
  }
}

export function remoteSlot<P extends object>(name: string, load: () => Promise<{ default: ComponentType<P> }>) {
  const Lazy = lazy(load);
  return function RemoteSlot(props: P) {
    return (
      <RemoteBoundary name={name} fallback={<p role="status">This section is unavailable right now.</p>}>
        <Suspense fallback={<div aria-busy="true" className="min-h-40" />}>
          <Lazy {...props} />
        </Suspense>
      </RemoteBoundary>
    );
  };
}

