// Cross-app contract: a versioned, typed DOM event instead of a shared store
export type CartUpdated = { v: 1; count: number };
export const emitCartUpdated = (detail: CartUpdated) =>
  window.dispatchEvent(new CustomEvent<CartUpdated>('acme:cart-updated', { detail }));
export const onCartUpdated = (fn: (d: CartUpdated) => void) => {
  const handler = (e: Event) => fn((e as CustomEvent<CartUpdated>).detail);
  window.addEventListener('acme:cart-updated', handler);
  return () => window.removeEventListener('acme:cart-updated', handler);
};
